            method: 'POST',
            data: {
              dbname: "itemInfo",
              dataSe: {
                array1: that.sizeList,
                array2: [1, 2, 3, 4, 5, 6, 7, 8, 9],
                des: that.des,
                flavor: "辣!",
                img: that.indexImg2,
                index1: 0,
                index2: 0,
                itemId: currentItemId,
                stitle: that.price,
                title: that.itemName } },


